#include "elit21/shopify/webhooks/ShopifyWebhookRegistrar.h"
namespace elit21::shopify::webhooks {ShopifyWebhookRegistrar::ShopifyWebhookRegistrar():platform::BusinessComponent("ShopifyWebhookRegistrar","Idempotent Shopify webhook subscription reconciler",platform::BusinessComponentSpec{"shopify","register_webhooks",{},true,true,4U*1024U*1024U}){}ShopifyWebhookRegistrar::ShopifyWebhookRegistrar(ShopifyClient&client,ShopifyConfig config):ShopifyWebhookRegistrar(){bind(client,std::move(config));}void ShopifyWebhookRegistrar::bind(ShopifyClient&client,ShopifyConfig config){client_=&client;config_=std::move(config);}Result<ShopifyWebhookRegistrySummary>ShopifyWebhookRegistrar::reconcile(bool dry_run){if(!client_)return Result<ShopifyWebhookRegistrySummary>::failure("ShopifyWebhookRegistrar is not bound");ShopifyWebhookRegistry registry(*client_,config_);return registry.reconcile(dry_run);}platform::OperationResult ShopifyWebhookRegistrar::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["client_bound"]=client_?1.0:0.0;r.metrics["required_topics"]=static_cast<double>(ShopifyWebhookRegistry::requiredTopics().size());return r;}}
